package kernels

import "math"

// ppc64le VSX kernels generated by go-asmgen (sum_ppc64le.s). VSX is part of
// the ppc64le baseline (POWER8, GOPPC64=power8), so they are always callable.
// Go's ppc64 assembler has no vector double arithmetic; go-asmgen encodes it
// (xvadddp, xvmaddadp, ...) as WORDs, checked against GNU as.
//
//go:generate sh -c "cd asmgen/ppc64le && go run . && mv sum_ppc64le.s ../../sum_ppc64le.s"

// HaveReduceSIMD reports that this build ships SIMD reduction/elementwise
// kernels.
const HaveReduceSIMD = true

// sumSIMD returns the VSX sum of a (empty -> 0): four accumulators, a valid
// regrouping of the sum, like the other targets' SIMD sums.
func sumSIMD(a []float64) float64 {
	if len(a) == 0 {
		return 0
	}
	return sumVSX(&a[0], len(a))
}

// sqrtSIMD writes sqrt(src[i]) into dst[i] with XVSQRTDP, bit-identical to
// math.Sqrt (one correctly rounded operation per lane).
func sqrtSIMD(dst, src []float64) {
	if len(dst) == 0 {
		return
	}
	_ = src[len(dst)-1] // the kernel reads len(dst) of src
	sqrtVSX(&dst[0], &src[0], len(dst))
}

// maxSIMD / minSIMD reduce whole blocks of 8 with xvmaxdp/xvmindp
// (sum_ppc64le.s) and fold the two lanes and the tail with Go's max/min.
// XVMAXDP/XVMINDP do not propagate NaN as Go and numpy.max do, so the kernel
// reports NaN separately: an integer magnitude test, OR-accumulated. Their sign
// of a zero tie is not Go's either, so a zero result goes to the scalar
// reducer, as on amd64.
func maxSIMD(a []float64) float64 {
	n := len(a) &^ 7
	if n == 0 {
		return maxUnrolled(a)
	}
	var out [2]float64
	if maxVSX(&a[0], n, &out) != 0 {
		return math.NaN()
	}
	m := max(out[0], out[1])
	for _, v := range a[n:] {
		m = max(m, v)
	}
	if m == 0 {
		return maxUnrolled(a)
	}
	return m
}

func minSIMD(a []float64) float64 {
	n := len(a) &^ 7
	if n == 0 {
		return minUnrolled(a)
	}
	var out [2]float64
	if minVSX(&a[0], n, &out) != 0 {
		return math.NaN()
	}
	m := min(out[0], out[1])
	for _, v := range a[n:] {
		m = min(m, v)
	}
	if m == 0 {
		return minUnrolled(a)
	}
	return m
}

//go:noescape
func maxVSX(a *float64, n int, out *[2]float64) int64

//go:noescape
func minVSX(a *float64, n int, out *[2]float64) int64

// addBin, subBin, mulBin, divBin write dst[i] = a[i] OP b[i] with the VSX
// kernels, each lane one IEEE operation, bit-identical to the scalar oracle.
func addBin(dst, a, b []float64) {
	if len(dst) > 0 {
		_, _ = a[len(dst)-1], b[len(dst)-1] // the kernel reads len(dst) of each
		addVSX(&dst[0], &a[0], &b[0], len(dst))
	}
}

func subBin(dst, a, b []float64) {
	if len(dst) > 0 {
		_, _ = a[len(dst)-1], b[len(dst)-1] // the kernel reads len(dst) of each
		subVSX(&dst[0], &a[0], &b[0], len(dst))
	}
}

func mulBin(dst, a, b []float64) {
	if len(dst) > 0 {
		_, _ = a[len(dst)-1], b[len(dst)-1] // the kernel reads len(dst) of each
		mulVSX(&dst[0], &a[0], &b[0], len(dst))
	}
}

func divBin(dst, a, b []float64) {
	if len(dst) > 0 {
		_, _ = a[len(dst)-1], b[len(dst)-1] // the kernel reads len(dst) of each
		divVSX(&dst[0], &a[0], &b[0], len(dst))
	}
}

//go:noescape
func sumVSX(a *float64, n int) float64

//go:noescape
func sqrtVSX(dst, src *float64, n int)

//go:noescape
func addVSX(dst, a, b *float64, n int)

//go:noescape
func subVSX(dst, a, b *float64, n int)

//go:noescape
func mulVSX(dst, a, b *float64, n int)

//go:noescape
func divVSX(dst, a, b *float64, n int)
